-- 185 · 27 BÀI VIẾT A2 CHO CÂY LUYỆN TẬP (03/11, lô 33).
--
-- Sinh bằng scripts/nhap/lo33_viet_a2.mjs từ lo33_viet_a2_noi_dung.mjs, không sửa tay file này.
-- 7 bài nền miễn phí, 20 bài VIP giá 19.000 đ; A2-PE-5 xếp sau 2 bài đã có. Bài gắn cây bằng
-- meta.kyNang, thuTu, vong. Mọi id bắt đầu bằng a2pe nên gỡ lại được theo tiền tố đó.

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe01pgz03j', 'practice', 'Écriture A2 : mon dernier week-end', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous écrivez à un ami pour raconter votre dernier week-end.</p><p>Dites ce que vous avez fait samedi et dimanche, avec qui, et si c''était bien. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le week-end dernier (expression) : cuối tuần trước\n• samedi matin (expression) : sáng thứ bảy\n• il a plu (expression) : trời đã mưa\n• rester (verbe) : ở lại\n• c''était… (expression) : (điều đó) đã rất…","explications":"• Kể việc đã xong dùng passé composé: nous avons visité, je suis allée.\n• Động từ đi với être thì phân từ hợp giống số với chủ ngữ: nous sommes allées.","kyNang":"A2-PE-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-03T13:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw000', 'a2pe01pgz03j', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Salut Hugo ! Le week-end dernier, je suis allée à Lyon chez ma cousine. Samedi matin, nous avons visité le vieux quartier et nous avons mangé dans un petit restaurant. Le soir, nous sommes allées au cinéma. Dimanche, il a plu, alors nous sommes restées à la maison et nous avons préparé un gâteau. C''était un très bon week-end ! Et toi, qu''est-ce que tu as fait ? Bises, Mai"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe02ph003k', 'practice', 'Écriture A2 : un voyage inoubliable', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous avez fait un beau voyage. Vous écrivez un article pour le blog de votre école.</p><p>Dites où vous êtes allé(e), avec qui, ce que vous avez fait et ce que vous avez aimé. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• partir (verbe) : khởi hành, đi\n• un paysage (nom masculin) : phong cảnh\n• goûter (verbe) : nếm thử\n• une spécialité (nom féminin) : đặc sản\n• inoubliable (adjectif) : không thể quên","explications":"• Trả lời đủ bốn ý của đề: đi đâu, với ai, làm gì, thích gì.\n• Thêm một câu cảm nhận cuối bài: C''est mon plus beau voyage !","kyNang":"A2-PE-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T13:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw001', 'a2pe02ph003k', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"L''été dernier, je suis parti à Da Lat avec deux amis. Nous avons pris le bus de nuit depuis Hô Chi Minh-Ville. Là-bas, il faisait frais et le paysage était magnifique. Nous avons visité des jardins de fleurs, nous avons fait du vélo autour du lac et nous avons goûté beaucoup de spécialités. Le dernier soir, nous avons regardé les étoiles. C''est mon plus beau voyage !"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe03ph003l', 'practice', 'Écriture A2 : le jour de mon anniversaire', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Racontez votre dernier anniversaire.</p><p>Décrivez d''abord la situation (où vous étiez, le temps, votre humeur), puis racontez ce qui s''est passé. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• loin de (expression) : xa\n• triste (adjectif) : buồn\n• un colocataire (nom masculin) : bạn ở chung nhà\n• offrir (verbe) : tặng\n• une surprise (nom féminin) : bất ngờ","explications":"• Bối cảnh (thời tiết, cảm xúc, khung cảnh) dùng imparfait: il faisait froid, j''étais triste.\n• Sự việc xảy ra rồi kết thúc dùng passé composé: ils ont chanté.","isPremium":true,"price":19000,"kyNang":"A2-PE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T13:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw002', 'a2pe03ph003l', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Pour mon dernier anniversaire, j''étais à Paris, loin de ma famille. C''était un dimanche et il faisait froid. J''étais un peu triste. Le soir, mon colocataire m''a proposé d''aller au restaurant. Quand nous sommes entrés, tous mes amis étaient là ! Ils ont chanté et ils m''ont offert un livre de cuisine française. J''ai beaucoup ri. C''était une très belle surprise."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe04ph103m', 'practice', 'Écriture A2 : une petite mésaventure', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Racontez un petit problème que vous avez eu (un retard, un objet perdu…).</p><p>Dites ce qui s''est passé, ce que vous avez ressenti et comment vous avez trouvé une solution. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un portefeuille (nom masculin) : ví\n• inquiet, inquiète (adjectif) : lo lắng\n• bloquer (verbe) : khoá\n• les objets trouvés (expression) : phòng đồ thất lạc\n• avoir de la chance (expression) : gặp may","explications":"• Kể theo trình tự: d''abord, ensuite, le lendemain.\n• Đừng quên nói cảm xúc: j''étais inquiet, j''ai eu de la chance.","isPremium":true,"price":19000,"kyNang":"A2-PE-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-03T13:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw003', 'a2pe04ph103m', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Mardi dernier, j''ai perdu mon portefeuille dans le bus. Je suis descendu à mon arrêt et, cinq minutes plus tard, j''ai vu que ma poche était vide ! J''étais très inquiet parce que ma carte bancaire était dedans. D''abord, j''ai appelé la banque pour bloquer la carte. Ensuite, je suis allé au bureau des objets trouvés. Le lendemain, une dame a rapporté mon portefeuille. J''ai eu de la chance !"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe05ph103n', 'practice', 'Écriture A2 : quand j''étais petit', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Racontez un souvenir d''enfance.</p><p>Décrivez où vous habitiez et ce que vous faisiez souvent, puis racontez un moment précis. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un souvenir (nom masculin) : kỷ niệm\n• l''enfance (nom féminin) : tuổi thơ\n• tous les après-midi (expression) : chiều nào cũng\n• un jour (expression) : một hôm\n• garder (verbe) : giữ lại, nuôi","explications":"• Việc lặp lại ngày xưa (tous les après-midi, souvent) dùng imparfait.\n• Un jour mở ra một sự việc cụ thể: chuyển sang passé composé.","isPremium":true,"price":19000,"kyNang":"A2-PE-1","vong":"on","thuTu":5}'::jsonb, '2026-11-03T13:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw004', 'a2pe05ph103n', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Quand j''étais petite, j''habitais chez mes grands-parents, dans un village près de Hué. Il y avait une rivière derrière la maison et tous les après-midi, je jouais avec mes cousins dans le jardin. Un jour, nous avons trouvé un petit chat sous un arbre. Il avait faim et il pleurait. Nous l''avons gardé et ma grand-mère l''a appelé Mít. Je n''ai jamais oublié ce jour."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe06ph103o', 'practice', 'Écriture A2 : racontez votre sortie', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous êtes allé(e) à un concert, un spectacle ou une fête avec des amis.</p><p>Vous écrivez un message sur votre blog pour raconter cette sortie : où, quand, avec qui, ce que vous avez fait et ce que vous avez pensé. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une sortie (nom féminin) : buổi đi chơi\n• un collègue (nom masculin) : đồng nghiệp\n• l''ambiance (nom féminin) : bầu không khí\n• une scène (nom féminin) : sân khấu\n• génial, géniale (adjectif) : tuyệt vời","explications":"• Đây là dạng bài 1 của đề DELF A2: kể một trải nghiệm, từ 60 từ.\n• Trước khi nộp, gạch đủ năm ý của đề: ở đâu, khi nào, với ai, làm gì, nghĩ gì.","isPremium":true,"price":19000,"kyNang":"A2-PE-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-03T13:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw005', 'a2pe06ph103o', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Samedi dernier, je suis allé au festival de musique de ma ville avec mes collègues. Nous sommes arrivés vers dix-huit heures. Il y avait beaucoup de monde et l''ambiance était géniale. D''abord, nous avons écouté un groupe de jazz, puis nous avons dansé devant la grande scène. Ensuite, nous avons mangé des crêpes. Nous sommes rentrés à minuit, très fatigués mais contents. C''était une soirée inoubliable !"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe07ph103p', 'practice', 'Écriture A2 : c''était super', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Pour chaque situation, donnez votre avis en une ou deux phrases.</p><p>Utilisez c''était, j''ai trouvé… et des adjectifs : génial, ennuyeux, délicieux, décevant…</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• passionnant, passionnante (adjectif) : hấp dẫn\n• ennuyeux, ennuyeuse (adjectif) : chán\n• délicieux, délicieuse (adjectif) : ngon\n• décevant, décevante (adjectif) : đáng thất vọng\n• bruyant, bruyante (adjectif) : ồn ào","explications":"• Nói cảm nhận về việc đã qua: C''était + tính từ.\n• Thêm rất, hơi, quá để rõ mức độ: très, un peu, trop.","kyNang":"A2-PE-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-03T13:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw006', 'a2pe07ph103p', 1, 'open', 'Un film que vous avez vu récemment.', '{}'::jsonb, '{"model":"J''ai vu un film d''aventure. C''était passionnant, mais un peu trop long."}'::jsonb, null), ('qmw065pgw007', 'a2pe07ph103p', 2, 'open', 'Un repas au restaurant.', '{}'::jsonb, '{"model":"Le restaurant était très agréable et les plats étaient délicieux."}'::jsonb, null), ('qmw065pgw008', 'a2pe07ph103p', 3, 'open', 'Une ville que vous avez visitée.', '{}'::jsonb, '{"model":"J''ai trouvé Paris magnifique, mais la ville est très chère."}'::jsonb, null), ('qmw065pgw009', 'a2pe07ph103p', 4, 'open', 'Un concert ou un spectacle.', '{}'::jsonb, '{"model":"Le concert était génial ! Le chanteur avait une voix superbe."}'::jsonb, null), ('qmw065pgw00a', 'a2pe07ph103p', 5, 'open', 'Un livre que vous avez lu.', '{}'::jsonb, '{"model":"Ce livre m''a beaucoup plu parce que l''histoire est très drôle."}'::jsonb, null), ('qmw065pgw00b', 'a2pe07ph103p', 6, 'open', 'Un hôtel où vous n''avez pas aimé dormir.', '{}'::jsonb, '{"model":"L''hôtel était décevant : la chambre était sale et très bruyante."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe08ph103q', 'practice', 'Écriture A2 : j''ai adoré parce que', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous avez vu un film ou lu un livre. Vous écrivez à un ami pour lui donner votre avis.</p><p>Donnez au moins deux raisons. (50 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• j''ai adoré (expression) : mình rất thích\n• touchant, touchante (adjectif) : cảm động\n• un acteur (nom masculin) : diễn viên\n• en plus (expression) : thêm nữa\n• conseiller (verbe) : khuyên","explications":"• Mỗi ý kiến kèm một lý do: J''ai adoré parce que…\n• En plus giúp thêm lý do thứ hai mà không lặp parce que.","isPremium":true,"price":19000,"kyNang":"A2-PE-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T13:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00c', 'a2pe08ph103q', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Salut Léa ! Hier soir, j''ai vu un film français sur une famille qui part en vacances en Bretagne. J''ai adoré ce film parce que l''histoire est drôle et touchante. Les acteurs sont excellents, surtout la petite fille. En plus, les paysages sont magnifiques. Le seul problème, c''est la fin : elle est un peu triste. Je te le conseille ! Bises, Hoa"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe09ph203r', 'practice', 'Écriture A2 : mon avis sur ce restaurant', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous avez dîné dans un nouveau restaurant. Vous écrivez un avis sur un site internet.</p><p>Dites ce que vous avez aimé et ce que vous n''avez pas aimé. (50 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un avis (nom masculin) : ý kiến, đánh giá\n• un serveur (nom masculin) : người phục vụ\n• par contre (expression) : ngược lại\n• élevé, élevée (adjectif) : cao\n• pressé, pressée (adjectif) : vội","explications":"• Khen trước, chê sau, nối bằng par contre hoặc mais.\n• Câu cuối nên là lời khuyên: Je recommande…","isPremium":true,"price":19000,"kyNang":"A2-PE-2","vong":"on","thuTu":3}'::jsonb, '2026-11-03T13:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00d', 'a2pe09ph203r', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Samedi soir, j''ai dîné au restaurant Le Petit Jardin avec ma famille. La salle est jolie et calme, et les serveurs sont très gentils. J''ai pris un poisson avec des légumes : c''était délicieux ! Par contre, nous avons attendu quarante minutes pour le dessert et les prix sont un peu élevés. Je recommande ce restaurant, mais pas quand on est pressé."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe10ph203s', 'practice', 'Écriture A2 : mes impressions', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le début du récit de Minh.</p><p>Écrivez la fin du récit : Minh donne ses impressions sur le voyage (ce qu''il a aimé, ce qu''il n''a pas aimé). (40 mots minimum)</p>', '<p>Le mois dernier, je suis allé à Hoi An avec mon frère. Nous avons pris le train jusqu''à Da Nang, puis un taxi. Nous avons visité la vieille ville, nous avons fait un tour en bateau et nous avons acheté des lanternes.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une impression (nom féminin) : cảm nhận\n• vraiment (adverbe) : thật sự\n• une lanterne (nom féminin) : đèn lồng\n• avoir envie de (expression) : muốn\n• retourner (verbe) : quay lại","explications":"• Bài kể ở đề thi nên kết bằng một đoạn cảm nhận.\n• Giữ đúng ngôi của người kể: ở đây là je, vì Minh tự kể.","isPremium":true,"price":19000,"kyNang":"A2-PE-2","vong":"chot","thuTu":4}'::jsonb, '2026-11-03T13:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00e', 'a2pe10ph203s', 1, 'open', 'Écrivez la fin du récit.', '{}'::jsonb, '{"model":"Ce voyage était vraiment génial. J''ai adoré la vieille ville parce que les maisons sont très belles, surtout le soir avec les lanternes. Les gens étaient gentils et la cuisine était délicieuse. Par contre, il faisait très chaud. J''ai envie d''y retourner l''année prochaine !"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe11ph203t', 'practice', 'Écriture A2 : viens à ma fête', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous organisez une fête pour la fin de vos études. Vous écrivez à vos amis.</p><p>Vous les invitez, vous donnez la date, l''heure et le lieu, et vous dites ce qu''ils peuvent apporter. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• organiser (verbe) : tổ chức\n• à partir de (expression) : từ (giờ nào)\n• il y aura (expression) : sẽ có\n• apporter (verbe) : mang theo\n• répondez-moi (expression) : hãy trả lời mình","explications":"• Thư mời phải có đủ: dịp gì, ngày, giờ, địa điểm.\n• Viết cho nhiều bạn thì dùng vous: Venez, Répondez-moi.","kyNang":"A2-PE-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-03T13:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00f', 'a2pe11ph203t', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Salut tout le monde ! J''ai enfin fini mes études, alors je fais une fête samedi 14 juin, à partir de 19 heures, chez moi, 12 rue des Lilas. Il y aura de la musique et un grand buffet. Vous pouvez apporter une boisson ou un dessert, si vous voulez. Venez avec vos amis ! Répondez-moi avant mercredi, s''il vous plaît, pour savoir combien vous serez. À samedi ! Linh"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe12ph203u', 'practice', 'Écriture A2 : merci pour ton cadeau', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Votre amie Claire vous a envoyé un cadeau pour votre anniversaire.</p><p>Vous la remerciez, vous dites ce que vous pensez du cadeau et vous racontez votre anniversaire. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• merci pour (expression) : cảm ơn vì\n• un foulard (nom masculin) : khăn quàng\n• doux, douce (adjectif) : mềm mại\n• porter (verbe) : mặc, đeo\n• tu m''as manqué (expression) : mình nhớ bạn","explications":"• Cảm ơn ngay câu đầu, rồi mới kể chuyện.\n• Nói cụ thể vì sao thích món quà: màu sắc, chất liệu, đã dùng chưa.","kyNang":"A2-PE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T13:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00g', 'a2pe12ph203u', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Chère Claire, merci beaucoup pour ton joli cadeau ! J''adore ce foulard bleu : la couleur est superbe et il est très doux. Je l''ai déjà porté au travail et mes collègues l''ont trouvé très beau. Pour mon anniversaire, j''ai fait un petit dîner avec ma famille. Ma mère a préparé mon plat préféré et nous avons mangé un gros gâteau au chocolat. Tu m''as manqué ! J''espère te voir bientôt. Bisous, Thu"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe13ph203v', 'practice', 'Écriture A2 : oui, je viens', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le message d''Antoine.</p><p>Vous lui répondez : vous acceptez l''invitation, vous posez une question et vous proposez d''apporter quelque chose. (60 mots minimum)</p>', '<p>Salut ! Dimanche prochain, je fais un pique-nique au parc avec quelques amis, à partir de midi. Tu veux venir ? Antoine</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• avec plaisir (expression) : rất sẵn lòng\n• un pique-nique (nom masculin) : buổi dã ngoại\n• se retrouver (verbe) : gặp nhau\n• une entrée (nom féminin) : cổng vào\n• s''il pleut (expression) : nếu trời mưa","explications":"• Nhận lời: Oui, je viens avec plaisir ! Từ chối: Désolé, je ne peux pas, kèm lý do.\n• Câu hỏi giúp bức thư tự nhiên và là một ý đề yêu cầu.","isPremium":true,"price":19000,"kyNang":"A2-PE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T13:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00h', 'a2pe13ph203v', 1, 'open', 'Écrivez votre réponse.', '{}'::jsonb, '{"model":"Salut Antoine ! Merci pour ton invitation, c''est une très bonne idée. Oui, je viens avec plaisir ! Est-ce que je peux venir avec ma sœur ? Elle passe le week-end chez moi. Je vais apporter une salade de riz et des fruits. On se retrouve à quelle entrée du parc ? Et s''il pleut, qu''est-ce qu''on fait ? Dis-moi. À dimanche ! Quang"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe14ph303w', 'practice', 'Écriture A2 : félicitations', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Votre collègue Sophie vient d''avoir un bébé.</p><p>Vous la félicitez, vous lui demandez des nouvelles et vous proposez de venir la voir. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• félicitations (nom féminin pluriel) : chúc mừng\n• la naissance (nom féminin) : sự ra đời\n• une équipe (nom féminin) : nhóm\n• des nouvelles (nom féminin pluriel) : tin tức\n• passer chez quelqu''un (expression) : ghé nhà ai","explications":"• Félicitations pour + danh từ: pour ton mariage, pour ton diplôme.\n• Kết thư thân mật: Je t''embrasse, Bises, Bisous.","isPremium":true,"price":19000,"kyNang":"A2-PE-3","vong":"on","thuTu":4}'::jsonb, '2026-11-03T13:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00i', 'a2pe14ph303w', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Chère Sophie, félicitations pour la naissance de ta petite Emma ! Toute l''équipe est très contente pour toi. Comment est-ce que tu vas ? Est-ce que le bébé dort bien la nuit ? Ici, au bureau, tout va bien, mais tu nous manques. Si tu veux, je peux passer chez toi la semaine prochaine avec un petit cadeau. Dis-moi quel jour est le mieux pour toi. Je t''embrasse, Hanh"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe15ph303x', 'practice', 'Écriture A2 : répondez à votre ami', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous recevez ce message de votre ami Julien.</p><p>Vous lui répondez : vous acceptez de le voir, vous proposez un jour et vous lui donnez deux idées de sorties. (60 mots minimum)</p>', '<p>Salut ! Je vais passer trois jours dans ta ville le mois prochain pour le travail. On peut se voir ? Tu as des idées de choses à faire le soir ? Julien</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• quelle bonne nouvelle (expression) : tin vui quá\n• être libre (expression) : rảnh\n• venir chercher (expression) : đến đón\n• se promener (verbe) : đi dạo\n• ça te va ? (expression) : bạn thấy được không?","explications":"• Đây là dạng bài 2 của đề DELF A2: trả lời thư, từ 60 từ.\n• Đề yêu cầu hai ý tưởng đi chơi: viết đủ hai, đừng viết một.","isPremium":true,"price":19000,"kyNang":"A2-PE-3","vong":"chot","thuTu":5}'::jsonb, '2026-11-03T13:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00j', 'a2pe15ph303x', 1, 'open', 'Écrivez votre réponse.', '{}'::jsonb, '{"model":"Salut Julien ! Quelle bonne nouvelle ! Bien sûr, je veux te voir. Est-ce que tu es libre jeudi soir ? Je peux venir te chercher à ton hôtel vers 19 heures. On peut d''abord se promener au bord du fleuve, c''est très joli le soir. Ensuite, je t''invite dans un petit restaurant vietnamien près de chez moi : leur soupe est délicieuse ! Dis-moi si ça te va. À bientôt, Nam"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe16ph403y', 'practice', 'Écriture A2 : désolé, je ne peux pas', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Votre amie Camille vous invite à son mariage le 20 juillet, mais vous ne pouvez pas venir.</p><p>Vous vous excusez, vous expliquez pourquoi et vous proposez autre chose. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• malheureusement (adverbe) : tiếc là\n• je suis désolé, désolée (expression) : mình rất tiếc, xin lỗi\n• rater (verbe) : bỏ lỡ\n• à mon retour (expression) : khi mình về\n• souhaiter (verbe) : chúc","explications":"• Thư xin lỗi có ba phần: xin lỗi, lý do, đề nghị khác.\n• Malheureusement mở đầu tin không vui một cách lịch sự.","kyNang":"A2-PE-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-03T13:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00k', 'a2pe16ph403y', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Chère Camille, merci beaucoup pour ton invitation, ça me touche vraiment. Malheureusement, je ne peux pas venir à ton mariage : le 20 juillet, je serai au Vietnam pour le mariage de mon frère. Je suis vraiment désolée de rater ce grand jour ! Je te propose de fêter ça ensemble à mon retour, en août. Je t''invite au restaurant avec ton mari. Je vous souhaite beaucoup de bonheur ! Bisous, Lan"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe17ph403z', 'practice', 'Écriture A2 : pourriez-vous m''aider ?', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Le chauffage de votre appartement ne marche pas depuis trois jours.</p><p>Vous écrivez au propriétaire, M. Durand : vous expliquez le problème et vous lui demandez de faire venir un technicien. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le chauffage (nom masculin) : hệ thống sưởi\n• fonctionner (verbe) : hoạt động\n• pourriez-vous… ? (expression) : ông, bà có thể… không?\n• un technicien (nom masculin) : thợ kỹ thuật\n• cordialement (adverbe) : trân trọng","explications":"• Viết cho chủ nhà dùng vous và giọng trang trọng: Bonjour Monsieur, Cordialement.\n• Pourriez-vous lịch sự hơn Pouvez-vous.","isPremium":true,"price":19000,"kyNang":"A2-PE-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T13:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00l', 'a2pe17ph403z', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Bonjour Monsieur Durand, je vous écris parce que le chauffage de mon appartement ne fonctionne plus depuis lundi. Il fait très froid, surtout la nuit, et ma fille est malade. Pourriez-vous envoyer un technicien cette semaine, s''il vous plaît ? Je suis à la maison tous les jours après 17 heures. Vous pouvez aussi m''appeler pour fixer un rendez-vous. Je vous remercie par avance. Cordialement, Mme Pham, appartement 4B"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe18ph5040', 'practice', 'Écriture A2 : changer de date', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous avez rendez-vous avec votre professeure, Mme Leroy, mardi à 10 heures, pour parler de votre projet. Vous ne pouvez pas venir.</p><p>Vous vous excusez, vous expliquez pourquoi et vous proposez deux autres moments. (60 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un rendez-vous (nom masculin) : cuộc hẹn\n• accompagner (verbe) : đi cùng\n• ce jour-là (expression) : hôm đó\n• nous pourrions (expression) : chúng ta có thể\n• excusez-moi (expression) : xin lỗi cô, thầy","explications":"• Đề nghị lịch khác bằng câu hỏi: Est-ce que nous pourrions… ?\n• Đưa hai lựa chọn để người nhận dễ trả lời.","isPremium":true,"price":19000,"kyNang":"A2-PE-4","vong":"on","thuTu":3}'::jsonb, '2026-11-03T13:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00m', 'a2pe18ph5040', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Bonjour Madame Leroy, je suis désolé, mais je ne pourrai pas venir à notre rendez-vous de mardi à 10 heures. Je dois accompagner ma mère à l''hôpital ce jour-là pour un examen. Est-ce que nous pourrions nous voir mercredi après-midi ou jeudi matin ? Je suis libre toute la journée ces deux jours. Excusez-moi encore pour ce changement. Bonne journée, Tuan Le"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe19ph5041', 'practice', 'Écriture A2 : je m''excuse', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Vous recevez ce message de votre amie Sarah.</p><p>Vous lui répondez : vous vous excusez, vous expliquez ce qui s''est passé et vous proposez une nouvelle sortie. (60 mots minimum)</p>', '<p>Je t''ai attendu une heure hier devant le cinéma ! Tu n''as pas répondu à mes messages. Je suis un peu fâchée. Sarah</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• fâché, fâchée (adjectif) : giận\n• une réunion (nom féminin) : cuộc họp\n• la batterie (nom féminin) : pin\n• prévenir (verbe) : báo trước\n• se faire pardonner (expression) : chuộc lỗi","explications":"• Đây là dạng bài 2 của đề DELF A2: thư xin lỗi, từ 60 từ.\n• Kể lý do bằng passé composé và imparfait: je suis restée, mon téléphone n''avait plus de batterie.","isPremium":true,"price":19000,"kyNang":"A2-PE-4","vong":"chot","thuTu":4}'::jsonb, '2026-11-03T13:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00n', 'a2pe19ph5041', 1, 'open', 'Écrivez votre réponse.', '{}'::jsonb, '{"model":"Chère Sarah, je suis vraiment désolée pour hier ! Tu as raison d''être fâchée. Je suis restée au bureau jusqu''à 19 heures pour une réunion et mon téléphone n''avait plus de batterie. Je n''ai pas pu te prévenir. Pardon ! Pour me faire pardonner, je t''invite au cinéma samedi soir et je paie les places et le dîner. Tu es d''accord ? Encore désolée. Bises, Vy"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe20ph5042', 'practice', 'Écriture A2 : elle est partie', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez le participe passé à la bonne forme.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• partir, parti (verbe) : rời đi\n• arriver, arrivé (verbe) : đến\n• naître, né (verbe) : sinh ra\n• venir, venu (verbe) : đến\n• tomber, tombé (verbe) : ngã","explications":"• Với être, phân từ hợp giống số với chủ ngữ như một tính từ.\n• Với avoir, phân từ không đổi theo chủ ngữ.","isPremium":true,"price":19000,"kyNang":"A2-PE-5","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T13:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw00o', 'a2pe20ph5042', 1, 'fill', 'Hier, Marie est ______ (partir) à huit heures.', '{}'::jsonb, '{"accepted":"partie"}'::jsonb, 'Đi với être, Marie là nữ: thêm -e.'), ('qmw065pgw00p', 'a2pe20ph5042', 2, 'fill', 'Mes parents sont ______ (arriver) dimanche.', '{}'::jsonb, '{"accepted":"arrivés"}'::jsonb, 'Parents là số nhiều, có nam: thêm -s.'), ('qmw065pgw00q', 'a2pe20ph5042', 3, 'fill', 'Les filles sont ______ (rentrer) tard.', '{}'::jsonb, '{"accepted":"rentrées"}'::jsonb, 'Giống cái số nhiều: thêm -es.'), ('qmw065pgw00r', 'a2pe20ph5042', 4, 'fill', 'Paul est ______ (tomber) dans la rue.', '{}'::jsonb, '{"accepted":"tombé"}'::jsonb, 'Paul là nam, số ít: giữ nguyên.'), ('qmw065pgw00s', 'a2pe20ph5042', 5, 'fill', 'Anna et moi, nous avons ______ (manger) au restaurant.', '{}'::jsonb, '{"accepted":"mangé"}'::jsonb, 'Đi với avoir: phân từ không đổi theo chủ ngữ.'), ('qmw065pgw00t', 'a2pe20ph5042', 6, 'fill', 'Elles ont ______ (visiter) le musée.', '{}'::jsonb, '{"accepted":"visité"}'::jsonb, 'Đi với avoir: không thêm -es.'), ('qmw065pgw00u', 'a2pe20ph5042', 7, 'fill', 'Ma sœur est ______ (naître) en 2010.', '{}'::jsonb, '{"accepted":"née"}'::jsonb, 'naître có phân từ né, giống cái là née.'), ('qmw065pgw00v', 'a2pe20ph5042', 8, 'fill', 'Léa et Sophie sont ______ (aller) à la plage.', '{}'::jsonb, '{"accepted":"allées"}'::jsonb, 'Hai bạn nữ: thêm -es.'), ('qmw065pgw00w', 'a2pe20ph5042', 9, 'fill', 'Mes amies ont ______ (prendre) le train.', '{}'::jsonb, '{"accepted":"pris"}'::jsonb, 'Đi với avoir: giữ pris.'), ('qmw065pgw00x', 'a2pe20ph5042', 10, 'fill', 'Ma grand-mère est ______ (venir) chez nous à Noël.', '{}'::jsonb, '{"accepted":"venue"}'::jsonb, 'venir có phân từ venu, giống cái là venue.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
