"accepted":"mais|pourtant|et pourtant"}'::jsonb, 'Hai ý ngược nhau.'), ('qmw065pgw02c', 'a2pe25ph5047', 7, 'fill', 'Je suis en retard ______ mon bus n''est pas passé.', '{}'::jsonb, '{"accepted":"parce que|car"}'::jsonb, 'Nguyên nhân.'), ('qmw065pgw02d', 'a2pe25ph5047', 8, 'ordre', 'Remettez les mots en ordre.', '{"elements":[{"id":"emw065pgw02h","texte":"donc"},{"id":"emw065pgw02e","texte":"J''aime beaucoup Paris,"},{"id":"emw065pgw02i","texte":"je n''y vais pas souvent."},{"id":"emw065pgw02g","texte":"c''est une ville chère,"},{"id":"emw065pgw02f","texte":"mais"}]}'::jsonb, '{"elements":[{"id":"emw065pgw02e","texte":"J''aime beaucoup Paris,"},{"id":"emw065pgw02f","texte":"mais"},{"id":"emw065pgw02g","texte":"c''est une ville chère,"},{"id":"emw065pgw02h","texte":"donc"},{"id":"emw065pgw02i","texte":"je n''y vais pas souvent."}]}'::jsonb, 'Mais nối ý ngược, donc dẫn tới kết quả.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe26ph5048', 'practice', 'Écriture A2 : remettez le texte en ordre', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Remettez les phrases en ordre pour retrouver le texte.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un vieil ami (expression) : bạn cũ\n• disparaître (verbe) : biến mất\n• chercher (verbe) : tìm\n• à l''arrivée (expression) : khi đến nơi\n• le lendemain (expression) : hôm sau","explications":"• Câu có lời chào luôn đứng đầu, câu có tên người viết đứng cuối.\n• Le lendemain, un jour, le soir là mốc thời gian giúp xếp thứ tự.","isPremium":true,"price":19000,"kyNang":"A2-PE-6","vong":"on","thuTu":3}'::jsonb, '2026-11-03T13:00:25.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw02j', 'a2pe26ph5048', 1, 'ordre', 'Texte 1', '{"elements":[{"id":"emw065pgw02l","texte":"D''abord, j''ai acheté des légumes."},{"id":"emw065pgw02k","texte":"Samedi dernier, je suis allé au marché."},{"id":"emw065pgw02m","texte":"Ensuite, j''ai pris du pain à la boulangerie."},{"id":"emw065pgw02o","texte":"Enfin, nous avons bu un café ensemble."},{"id":"emw065pgw02n","texte":"Puis, j''ai rencontré un vieil ami."}]}'::jsonb, '{"elements":[{"id":"emw065pgw02k","texte":"Samedi dernier, je suis allé au marché."},{"id":"emw065pgw02l","texte":"D''abord, j''ai acheté des légumes."},{"id":"emw065pgw02m","texte":"Ensuite, j''ai pris du pain à la boulangerie."},{"id":"emw065pgw02n","texte":"Puis, j''ai rencontré un vieil ami."},{"id":"emw065pgw02o","texte":"Enfin, nous avons bu un café ensemble."}]}'::jsonb, 'Từ trình tự cho biết thứ tự.'), ('qmw065pgw02p', 'a2pe26ph5048', 2, 'ordre', 'Texte 2', '{"elements":[{"id":"emw065pgw02q","texte":"Chère Anne,"},{"id":"emw065pgw02u","texte":"Bises, Mai"},{"id":"emw065pgw02s","texte":"Ma fille est malade et je dois rester avec elle."},{"id":"emw065pgw02t","texte":"On peut se voir samedi ?"},{"id":"emw065pgw02r","texte":"Je suis désolée, je ne peux pas venir ce soir."}]}'::jsonb, '{"elements":[{"id":"emw065pgw02q","texte":"Chère Anne,"},{"id":"emw065pgw02r","texte":"Je suis désolée, je ne peux pas venir ce soir."},{"id":"emw065pgw02s","texte":"Ma fille est malade et je dois rester avec elle."},{"id":"emw065pgw02t","texte":"On peut se voir samedi ?"},{"id":"emw065pgw02u","texte":"Bises, Mai"}]}'::jsonb, 'Chào, xin lỗi, lý do, đề nghị, kết thư.'), ('qmw065pgw02v', 'a2pe26ph5048', 3, 'ordre', 'Texte 3', '{"elements":[{"id":"emw065pgw02w","texte":"Quand j''étais petit, j''habitais à la campagne."},{"id":"emw065pgw02x","texte":"Il y avait un grand jardin derrière la maison."},{"id":"emw065pgw02y","texte":"Un jour, mon chien a disparu."},{"id":"emw065pgw02z","texte":"Nous l''avons cherché toute la journée."},{"id":"emw065pgw030","texte":"Le soir, il est enfin rentré à la maison."}]}'::jsonb, '{"elements":[{"id":"emw065pgw02w","texte":"Quand j''étais petit, j''habitais à la campagne."},{"id":"emw065pgw02x","texte":"Il y avait un grand jardin derrière la maison."},{"id":"emw065pgw02y","texte":"Un jour, mon chien a disparu."},{"id":"emw065pgw02z","texte":"Nous l''avons cherché toute la journée."},{"id":"emw065pgw030","texte":"Le soir, il est enfin rentré à la maison."}]}'::jsonb, 'Bối cảnh trước, rồi un jour mở ra sự việc.'), ('qmw065pgw031', 'a2pe26ph5048', 4, 'ordre', 'Texte 4', '{"elements":[{"id":"emw065pgw034","texte":"À l''arrivée, nous avons pris un taxi jusqu''à l''hôtel."},{"id":"emw065pgw033","texte":"Nous avons pris l''avion à Paris."},{"id":"emw065pgw036","texte":"C''était un voyage fantastique !"},{"id":"emw065pgw035","texte":"Le lendemain, nous avons visité le Colisée."},{"id":"emw065pgw032","texte":"L''été dernier, nous sommes partis en Italie."}]}'::jsonb, '{"elements":[{"id":"emw065pgw032","texte":"L''été dernier, nous sommes partis en Italie."},{"id":"emw065pgw033","texte":"Nous avons pris l''avion à Paris."},{"id":"emw065pgw034","texte":"À l''arrivée, nous avons pris un taxi jusqu''à l''hôtel."},{"id":"emw065pgw035","texte":"Le lendemain, nous avons visité le Colisée."},{"id":"emw065pgw036","texte":"C''était un voyage fantastique !"}]}'::jsonb, 'Theo thời gian, cảm nhận ở cuối.'), ('qmw065pgw037', 'a2pe26ph5048', 5, 'ordre', 'Texte 5', '{"elements":[{"id":"emw065pgw03c","texte":"À samedi, Linh"},{"id":"emw065pgw03a","texte":"Je fais une fête chez moi à 20 heures."},{"id":"emw065pgw038","texte":"Salut Hugo !"},{"id":"emw065pgw039","texte":"Samedi, c''est mon anniversaire."},{"id":"emw065pgw03b","texte":"Est-ce que tu peux apporter de la musique ?"}]}'::jsonb, '{"elements":[{"id":"emw065pgw038","texte":"Salut Hugo !"},{"id":"emw065pgw039","texte":"Samedi, c''est mon anniversaire."},{"id":"emw065pgw03a","texte":"Je fais une fête chez moi à 20 heures."},{"id":"emw065pgw03b","texte":"Est-ce que tu peux apporter de la musique ?"},{"id":"emw065pgw03c","texte":"À samedi, Linh"}]}'::jsonb, 'Chào, dịp gì, lời mời, câu hỏi, kết thư.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2pe27ph6049', 'practice', 'Écriture A2 : un seul paragraphe', 'A2', array['Production écrite']::text[], 'practice', null, null, '<p>Reliez les deux phrases avec le bon mot de liaison.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• relier (verbe) : nối\n• un mot de liaison (expression) : từ nối\n• rater (verbe) : lỡ\n• neiger (verbe) : có tuyết\n• s''habiller (verbe) : mặc quần áo","explications":"• Tự hỏi: câu sau là nguyên nhân, kết quả, ý ngược hay bước tiếp theo.\n• Nối câu ngắn thành câu dài giúp ăn điểm mạch lạc ở bài viết A2.","isPremium":true,"price":19000,"kyNang":"A2-PE-6","vong":"chot","thuTu":4}'::jsonb, '2026-11-03T13:00:26.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw065pgw03d', 'a2pe27ph6049', 1, 'fill', 'Je suis arrivé à la gare en retard. J''ai raté mon train. → Je suis arrivé à la gare en retard, ______ j''ai raté mon train.', '{}'::jsonb, '{"accepted":"donc|alors"}'::jsonb, 'Kết quả.'), ('qmw065pgw03e', 'a2pe27ph6049', 2, 'fill', 'Nous sommes restés à la maison. Il neigeait. → Nous sommes restés à la maison ______ il neigeait.', '{}'::jsonb, '{"accepted":"parce que|car"}'::jsonb, 'Nguyên nhân.'), ('qmw065pgw03f', 'a2pe27ph6049', 3, 'fill', 'Le musée était fermé. Nous ne l''avons pas visité. → Le musée était fermé, ______ nous ne l''avons pas visité.', '{}'::jsonb, '{"accepted":"donc|alors"}'::jsonb, 'Kết quả.'), ('qmw065pgw03g', 'a2pe27ph6049', 4, 'fill', 'J''ai appelé Marc. Il n''a pas répondu. → J''ai appelé Marc, ______ il n''a pas répondu.', '{}'::jsonb, '{"accepted":"mais"}'::jsonb, 'Điều mong đợi không xảy ra: mais.'), ('qmw065pgw03h', 'a2pe27ph6049', 5, 'fill', 'J''ai pris une douche. Je me suis habillé. → D''abord, j''ai pris une douche, ______ je me suis habillé.', '{}'::jsonb, '{"accepted":"puis|ensuite|et puis|et ensuite"}'::jsonb, 'Bước tiếp theo.'), ('qmw065pgw03i', 'a2pe27ph6049', 6, 'fill', 'Il faisait beau. Nous avons fait un pique-nique. → ______ il faisait beau, nous avons fait un pique-nique.', '{}'::jsonb, '{"accepted":"Comme|Puisque"}'::jsonb, 'Nguyên nhân đứng đầu câu: comme.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare n int;
begin
  select count(*) into n from public.exercises where id like 'a2pe%';
